def prime_fib(n: int):
    fib_primes = []
    a, b = 0, 1
    def is_prime(num):
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True
    while len(fib_primes) < n:
        current = a + b
        if is_prime(current):
            fib_primes.append(current)
        a, b = b, current
    return fib_primes[-1]
```

